#pragma once

#include <string_view>
#include <vector>

namespace KCDC::Shared::Game {
    /**
     * One horse a script or a chat command can ask for by name.
     *
     * Generated by `tools/generate_horse_catalog.py`: every horse soul in
     * `Libs/Tables/rpg/soul__*.xml` that names a `skald_character`, which is
     * where a horse's coat, build and name come from -- the horses the game's
     * own traders sell, and the named horses of its quests. The hundreds of
     * quest extras that name none all look like the generic horse, which is
     * the first row.
     */
    struct HorseBreedEntry {
        /** What a script names it: `horse`, `pebbles`, `kluger_hans`. */
        std::string_view name;

        /** The English name the game gives this horse. */
        std::string_view displayName;

        /** `soul_id` of the soul the body is spawned against. */
        std::string_view soulGuid;

        /** `soul_name` of that soul, for anyone matching one up with the tables. */
        std::string_view soulName;
    };

    extern const std::vector<HorseBreedEntry> g_HorseBreeds;

    /** The breed with this name, or null; an unknown name is taken as a soul GUID by the caller. */
    const HorseBreedEntry *FindHorseBreed(std::string_view name);
} // namespace KCDC::Shared::Game
